#include <stdio.h>

static int degree[100001];

int main(void) {
    int vertices, edges;
    if (scanf("%d %d", &vertices, &edges) != 2 || vertices < 1 || vertices > 100000) {
        return 0;
    }
    for (int i = 0; i < edges; i++) {
        int u, v;
        if (scanf("%d %d", &u, &v) != 2) {
            break;
        }
        degree[u]++;
        degree[v]++;
    }
    long long sum = 0;
    for (int v = 1; v <= vertices; v++) {
        printf(v < vertices ? "%d " : "%d\n", degree[v]);
        sum += degree[v];
    }
    printf("сумма %lld = 2 · %d\n", sum, edges);
    return 0;
}

