#include <stdio.h>
#include <stdlib.h>

static int from[200000], to[200000];
static int start[100002], fill[100001];
static int neighbours[400000];

static int compare(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int vertices, edges;
    if (scanf("%d %d", &vertices, &edges) != 2 || vertices < 1 || vertices > 100000 || edges > 200000) {
        return 0;
    }
    for (int i = 0; i < edges; i++) {
        scanf("%d %d", &from[i], &to[i]);
        start[from[i] + 1]++;
        start[to[i] + 1]++;
    }
    for (int v = 1; v <= vertices + 1; v++) {
        start[v] += start[v - 1];
    }
    for (int v = 1; v <= vertices; v++) {
        fill[v] = start[v];
    }
    for (int i = 0; i < edges; i++) {
        neighbours[fill[from[i]]++] = to[i];
        neighbours[fill[to[i]]++] = from[i];
    }
    for (int v = 1; v <= vertices; v++) {
        qsort(&neighbours[start[v]], (size_t)(start[v + 1] - start[v]), sizeof(int), compare);
    }
    int a, b;
    while (scanf("%d %d", &a, &b) == 2) {
        int i = start[a], j = start[b], common = 0;
        while (i < start[a + 1] && j < start[b + 1]) {
            if (neighbours[i] < neighbours[j]) {
                i++;
            } else if (neighbours[i] > neighbours[j]) {
                j++;
            } else {
                common++;
                i++;
                j++;
            }
        }
        printf("%d\n", common);
    }
    return 0;
}

